const fs = require("node:fs");

function scanFile(content) {
  const issues = [];
  if (/var /.test(content)) issues.push("use-let-or-const");
  if (/==[^=]/.test(content)) issues.push("loose-equality");
  return issues;
}

function reviewAll(files) {
  return files
    .map(name => ({ file: name, issues: scanFile(fs.readFileSync(name, "utf8")) }))
    .filter(entry => entry.issues.length > 0);
}

module.exports = { reviewAll, scanFile };

