const { reviewAll } = require("./checker.js");

const files = process.argv.slice(2).filter(arg => arg.endsWith(".js"));
const findings = reviewAll(files);
for (const finding of findings) console.log(finding.file + ": " + finding.issues.join(", "));
if (findings.length === 0) console.log("clean");

